// [WHALE-CHAT-STRICT] 群会话的 target 只认入站会话 id（targetId / conversationId / chatId）：
// 缺了就丢弃并告警，**绝不**回退成 senderId —— 那是群里某个成员的 wxid，
// 拿它当 target 会把本该发到群里的回复打进这个成员的私聊。
const rawTarget = String(payload?.targetId ?? payload?.conversationId ?? payload?.chatId ?? '').trim();
const targetId = kind === 'group' ? rawTarget : (rawTarget || userId);
if (userId === '') return null;
if (targetId === '') {
	this.log?.('warn', `[fish-soul] 微信${kind === 'group' ? '群' : '私聊'}消息缺会话 id，丢弃（senderId=${userId}）`);
	return null;
}
if (kind === 'group' && targetId === userId) {
	this.log?.('warn', `[fish-soul] 微信群消息的 target 等于发送人 id（${userId}），疑似回退成 senderId，丢弃`);
	return null;
}
